@startuml

class Customer {
  + name : string
  + address : string
  + accountNumber : string
}

class Broker {
  + brokerId : int
  + name : string
  + contactDetails : string
}

class InsuranceProduct {
  + productId : int
  + description : string
  + basePrice : double
}

class Policy {
  + policyNumber : string
  + coverageType : string
  + startDate : date
  + endDate : date
}

class Contract {
  + contractId : int
  + signingDate : date
  + billingFrequency : string
  + totalPrice : double
}

class Offer {
  + offerId : int
  + expiryDate : date
  + status : string
}

class ClaimCase {
  + claimId : int
  + description : string
  + status : string
  + openingDate : date
}

class EstimatorReport {
  + reportId : int
  + content : string
  + expertiseArea : string
  + issueDate : date
}

class CompensationDecision {
  + decisionId : int
  + approvedAmount : double
  + eligibleCosts : string
}

class Payment {
  + paymentId : int
  + amount : double
  + paymentDate : date
}

Broker "1" -- "0..*" Customer : manages
Customer "1" -- "0..*" Contract : signs
Contract "1" -- "1..*" Policy : covers
Policy "0..*" -- "1" InsuranceProduct : type
Contract "1" -- "0..1" Offer : basedOn
Customer "1" -- "0..*" ClaimCase : files
ClaimCase "1" *-- "1..*" EstimatorReport : contains
EstimatorReport "0..*" -- "1" Estimator : issuedBy
ClaimCase "1" -- "0..1" CompensationDecision : resultsIn
CompensationDecision "1" -- "1" Payment : triggers
Payment "1" -- "1" Customer : paidTo

class Estimator {}

@enduml

